import{_ as t,o as e,c as o,ah as r}from"./chunks/framework.Yx0DUrwu.js";const m=JSON.parse('{"title":"Janeway 免疫学学习图谱","description":"","frontmatter":{},"headers":[],"relativePath":"biology/immunology-roadmap.md","filePath":"biology/immunology-roadmap.md","lastUpdated":1787828013000}'),n={name:"biology/immunology-roadmap.md"};function i(l,a,s,d,c,p){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="janeway-免疫学学习图谱" tabindex="-1">Janeway 免疫学学习图谱 <a class="header-anchor" href="#janeway-免疫学学习图谱" aria-label="Permalink to &quot;Janeway 免疫学学习图谱&quot;">​</a></h1><p>《詹韦免疫生物学》适合当作免疫学主干教材来读，但网站里的目标不是逐章复述，而是把教材知识重组为单细胞研究者更容易使用的结构：先知道免疫系统由谁组成，再理解它们怎样识别危险、怎样被激活、怎样执行效应功能，最后回到疾病、疫苗、肿瘤和组织微环境。</p><h2 id="总体框架" tabindex="-1">总体框架 <a class="header-anchor" href="#总体框架" aria-label="Permalink to &quot;总体框架&quot;">​</a></h2><div class="flow-strip"><span>免疫系统的任务</span><span>固有免疫快速识别</span><span>抗原识别与提呈</span><span>淋巴细胞发育</span><span>适应性免疫效应</span><span>记忆与耐受</span><span>黏膜和组织生态位</span><span>疾病与免疫治疗</span></div><h2 id="五大部分如何重组" tabindex="-1">五大部分如何重组 <a class="header-anchor" href="#五大部分如何重组" aria-label="Permalink to &quot;五大部分如何重组&quot;">​</a></h2><table tabindex="0"><thead><tr><th>教材主线</th><th>网站专题</th><th>学习目标</th><th>单细胞分析中的用途</th></tr></thead><tbody><tr><td>免疫生物学和固有免疫概论</td><td><a href="/sc-tools/biology/innate-immunity">固有免疫</a></td><td>理解屏障、补体、PRR、炎症、干扰素、NK 和 ILC。</td><td>解释 monocyte/macrophage/DC/neutrophil 的炎症状态和抗病毒程序。</td></tr><tr><td>抗原的识别</td><td><a href="/sc-tools/biology/antigen-recognition-presentation">抗原识别与抗原提呈</a></td><td>理解 BCR、TCR、MHC-I、MHC-II、交叉提呈和非经典提呈。</td><td>判断 APC、T cell activation、TCR clonotype 和抗原特异性线索。</td></tr><tr><td>成熟淋巴细胞受体库的产生</td><td><a href="/sc-tools/biology/lymphocyte-development-activation">淋巴细胞发育与活化</a></td><td>理解 V(D)J 重排、B/T 细胞选择、TCR/BCR signaling 和 checkpoint。</td><td>解释 naive、memory、Treg、plasma cell、cycling lymphocyte 等状态。</td></tr><tr><td>适应性免疫应答</td><td><a href="/sc-tools/biology/adaptive-effector-immunity">适应性免疫应答</a></td><td>理解 T cell priming、CD4/CD8 分化、B cell 生发中心和抗体功能。</td><td>支撑 T cell subtype、B cell maturation、effector gene program 的注释。</td></tr><tr><td>健康与疾病中的免疫系统</td><td><a href="/sc-tools/biology/mucosal-disease-immunotherapy">黏膜免疫、疾病与治疗</a></td><td>理解免疫缺陷、过敏、自身免疫、移植、疫苗和肿瘤免疫治疗。</td><td>把单细胞发现放回疾病机制、治疗响应和组织微环境。</td></tr></tbody></table><h2 id="免疫学最小概念集" tabindex="-1">免疫学最小概念集 <a class="header-anchor" href="#免疫学最小概念集" aria-label="Permalink to &quot;免疫学最小概念集&quot;">​</a></h2><div class="check-grid"><article><strong>识别</strong><span>固有免疫主要识别 conserved microbial patterns 和 tissue damage；适应性免疫通过 BCR/TCR 识别高度特异的抗原。</span></article><article><strong>放大</strong><span>细胞因子、趋化因子、补体和 clonal expansion 把局部信号变成系统性或组织级应答。</span></article><article><strong>效应</strong><span>吞噬、中和、补体裂解、细胞毒杀伤、巨噬细胞活化、屏障修复等机制共同清除威胁。</span></article><article><strong>调控</strong><span>中枢耐受、外周耐受、Treg、checkpoint receptor 和组织限制机制避免免疫应答伤害宿主。</span></article></div><h2 id="推荐阅读顺序" tabindex="-1">推荐阅读顺序 <a class="header-anchor" href="#推荐阅读顺序" aria-label="Permalink to &quot;推荐阅读顺序&quot;">​</a></h2><ol><li>先读 <a href="/sc-tools/biology/common-cell-types">常见细胞类型</a>，知道单细胞图上的主要免疫细胞是谁。</li><li>再读 <a href="/sc-tools/biology/innate-immunity">固有免疫</a>，理解炎症和抗病毒 gene program。</li><li>接着读 <a href="/sc-tools/biology/antigen-recognition-presentation">抗原识别与抗原提呈</a>，理解 T cell 和 APC 为什么要配对解释。</li><li>然后读 <a href="/sc-tools/biology/lymphocyte-development-activation">淋巴细胞发育与活化</a>，把 naive、activated、exhausted、Treg、plasma cell 等状态放进谱系。</li><li>最后读 <a href="/sc-tools/biology/adaptive-effector-immunity">适应性免疫应答</a> 和 <a href="/sc-tools/biology/mucosal-disease-immunotherapy">黏膜免疫、疾病与治疗</a>，进入疾病和组织场景。</li></ol><h2 id="单细胞读图提示" tabindex="-1">单细胞读图提示 <a class="header-anchor" href="#单细胞读图提示" aria-label="Permalink to &quot;单细胞读图提示&quot;">​</a></h2><div class="doc-callout warning"><strong>不要把 marker 当机制本身</strong><p>marker 可以帮助命名 cluster，但机制判断需要看细胞类型、受体/配体、转录因子、细胞因子、空间位置、样本设计和功能证据。免疫学教材提供的是解释坐标系，而不是替代实验验证的快捷答案。</p></div><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p>[1] Murphy, K. &amp; Weaver, C. <em>Janeway&#39;s Immunobiology</em>. 9th ed. Garland Science (2017). 中文版：《詹韦免疫生物学：原书第九版》，科学出版社，2022。</p>',14)])])}const g=t(n,[["render",i]]);export{m as __pageData,g as default};
